mapper.update:
update booknest.`chat_group`
set last_message = #{lastMessage}, last_msg_at = #{lastMsgAt}
where id = #{id}

update booknest.`chat_group`
name = #{name}, avatar = #{avatar}, notice = #{notice},
where id = #{id}

update booknest.`chat_group_member`
set last_read_at = #{lastReadAt}
where group_id = #{groupId} and user_id = #{userId}

mapper.select:
select count(*)
from booknest.`chat_message` msg
inner join booknest.`chat_group_member` m
        on m.group_id = msg.group_id and m.user_id = #{userId}
where msg.group_id = #{groupId}
  and msg.sender_id <> #{userId}
  and (m.last_read_at is null or msg.create_time > m.last_read_at)

select count(*)
from booknest.`chat_message` msg
inner join booknest.`chat_group_member` m
        on m.group_id = msg.group_id and m.user_id = #{userId}
where msg.sender_id <> #{userId}
  and (m.last_read_at is null or msg.create_time > m.last_read_at)
